def reduce_current(path,raw):
 raw=code_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS or type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed OAuth source')
 raw=assessment_delta.reduce_current(path,raw)
 for added,removed in EDITS[path]:
  if raw.count(added)!=1:raise ValueError('OAuth inverse shape changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('OAuth changed other main bytes')
 return raw
